        await activatePromise;
        const missesAtCheck: number[] = [];
        const outstanding: string[] = [];
        let terminatedAtMs: number | null = null;
        let beat = 0;
        for (const step of scenario.timeline) {
          if (terminatedAtMs !== null) break;
          setNow(step.atMs);
