    plugin,
    app,
    identity: options.identity ?? fixture.identities.a,
    instance: options.instance,
    baseUrl: "https://hub.example",
    bootstrapEpoch: 3,
    locale: "de-DE",
    terminology: "native",
    signal: options.signal,
    beforeBootstrap: options.beforeBootstrap,
    post: (message) => posts.push(message),
  });
}

